#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct radix_node {
    char *prefix;
    bool is_word;
    struct radix_node *children[256];
} radix_node;

radix_node *root = NULL;

char* my_strdup(const char *s) {
    size_t len = strlen(s);
    char *copy = malloc(len + 1);
    if(copy) memcpy(copy, s, len + 1);
    return copy;
}

char* my_strndup(const char *s, size_t n) {
    size_t len = 0;
    while(len < n && s[len] != '\0') len++;
    char *copy = malloc(len + 1);
    if(copy) {
        memcpy(copy, s, len);
        copy[len] = '\0';
    }
    return copy;
}

radix_node* create_node(const char *prefix, bool is_word) {
    radix_node *n = calloc(1, sizeof(radix_node));
    if (!n) abort();
    if (prefix) n->prefix = my_strdup(prefix);
    else n->prefix = my_strdup("");
    n->is_word = is_word;
    return n;
}

void _radix_insert(radix_node *curr, const char *word) {
    int i = 0;
    while (curr->prefix[i] != '\0' && word[i] != '\0' && curr->prefix[i] == word[i]) {
        i++;
    }

    if (curr->prefix[i] != '\0') {
        radix_node *split_node = calloc(1, sizeof(radix_node));
        split_node->prefix = my_strdup(curr->prefix + i);
        split_node->is_word = curr->is_word;
        memcpy(split_node->children, curr->children, sizeof(curr->children));

        char *new_prefix = my_strndup(curr->prefix, i);
        free(curr->prefix);
        curr->prefix = new_prefix;
        curr->is_word = false;

        memset(curr->children, 0, sizeof(curr->children));
        curr->children[(unsigned char)split_node->prefix[0]] = split_node;
    }

    const char *rem = word + i;
    if (rem[0] == '\0') {
        curr->is_word = true;
    } else {
        unsigned char c = (unsigned char)rem[0];
        if (curr->children[c]) {
            _radix_insert(curr->children[c], rem);
        } else {
            curr->children[c] = create_node(rem, true);
        }
    }
}

void radix_insert(const char *word) {
    if (!root) {
        root = create_node("", false);
    }
    _radix_insert(root, word);
}

void radix_free(radix_node *node) {
    if (!node) return;
    for (int k = 0; k < 256; k++) {
        if (node->children[k]) {
            radix_free(node->children[k]);
        }
    }
    free(node->prefix);
    free(node);
}

bool _radix_delete(radix_node *curr, const char *word) {
    int i = 0;
    while (curr->prefix[i] != '\0' && word[i] != '\0' && curr->prefix[i] == word[i]) {
        i++;
    }

    if (curr->prefix[i] != '\0') return false;

    const char *rem = word + i;
    if (rem[0] == '\0') {
        if (!curr->is_word) return false;
        curr->is_word = false;
    } else {
        unsigned char c = (unsigned char)rem[0];
        if (!curr->children[c]) return false;
        bool child_deleted = _radix_delete(curr->children[c], rem);
        if (child_deleted) {
            free(curr->children[c]->prefix);
            free(curr->children[c]);
            curr->children[c] = NULL;
        }
    }

    int child_count = 0;
    int last_child_index = -1;
    for (int k = 0; k < 256; k++) {
        if (curr->children[k]) {
            child_count++;
            last_child_index = k;
        }
    }

    if (child_count == 0 && !curr->is_word) {
        return true;
    }

    if (child_count == 1 && !curr->is_word) {
        radix_node *child = curr->children[last_child_index];
        char *merged_prefix = malloc(strlen(curr->prefix) + strlen(child->prefix) + 1);
        if (merged_prefix) {
            strcpy(merged_prefix, curr->prefix);
            strcat(merged_prefix, child->prefix);
            free(curr->prefix);
            curr->prefix = merged_prefix;
            curr->is_word = child->is_word;
            for(int k = 0; k < 256; k++) {
                curr->children[k] = child->children[k];
            }
            free(child->prefix);
            free(child);
        }
    }

    return false;
}

void radix_delete(const char *word) {
    if (!root) return;
    if (_radix_delete(root, word)) {
        free(root->prefix);
        free(root);
        root = NULL;
    }
}

bool radix_search(const char *word) {
    if (!root) return false;
    radix_node *curr = root;
    const char *rem = word;
    while (1) {
        int i = 0;
        while (curr->prefix[i] != '\0' && rem[i] != '\0' && curr->prefix[i] == rem[i]) {
            i++;
        }
        if (curr->prefix[i] != '\0') {
            return false;
        }
        rem = rem + i;
        if (rem[0] == '\0') {
            return curr->is_word;
        }
        unsigned char c = (unsigned char)rem[0];
        if (!curr->children[c]) {
            return false;
        }
        curr = curr->children[c];
    }
}

int main() {
    printf("Starting Radix Tree ASAN Stress Test...\n");

    for (int i = 0; i < 2000; i++) {
        char buf[32];
        snprintf(buf, sizeof(buf), "word%04dtest", i);
        radix_insert(buf);
    }

    for (int i = 0; i < 1000; i++) {
        char buf[32];
        snprintf(buf, sizeof(buf), "word%04dtest", i);
        radix_delete(buf);
    }

    for (int i = 0; i < 2000; i++) {
        char buf[32];
        snprintf(buf, sizeof(buf), "word%04dtest", i);
        bool found = radix_search(buf);
        if (i < 1000 && found) {
            printf("Invariant violated: Valid word %s found after deletion!\n", buf);
            return 1;
        }
        if (i >= 1000 && !found) {
            printf("Invariant violated: Valid word %s not found after compaction!\n", buf);
            return 1;
        }
    }

    radix_free(root);
    root = NULL;

    printf("FLAG: Radix Tree ASAN Success!\n");
    return 0;
}
